from h import build
R=[
(3300792,"Tofu braisé aux champignons",
"Ce repas est faible en potassium et en phosphate, mais constitue une bonne source de protéines sans viande pour une personne sous dialyse.",
"4",None,
["300 g de riz blanc","160 g de carottes, pelées et tranchées","2 pak-choï, tranchés","1 touffe de pleurotes (environ 150 g)","2 pleurotes du panicaut (environ 200 g)","2 cuillères à soupe d'huile végétale","700 g (2 cartons) de tofu ferme/extra-ferme","1 cuillère à soupe de sauce aux huîtres (utilisez une version végétarienne pour que ce plat soit végétarien/végane)","1 cuillère à soupe de sauce soja à faible teneur en sel","1 cuillère à soupe de sucre extra-fin","2 cuillères à café de fécule de maïs","2 gousses d'ail, finement hachées (facultatif)"],
["Faites cuire le riz selon les instructions sur l'emballage. Faites blanchir les carottes et le pak-choï 5 à 10 minutes, puis égouttez l'eau.","Séparez les pleurotes de la touffe et tranchez les pleurotes du panicaut.","Faites frire le tofu dans une poêle avec une cuillère à soupe d'huile jusqu'à ce qu'il soit doré des deux côtés. Faites cuire par lots jusqu'à ce que tout le tofu soit cuit (environ 5 minutes de chaque côté). Déposez le tofu sur une assiette propre garnie de papier absorbant pour absorber l'excès d'huile.","Ajoutez l'ail (le cas échéant), les carottes, les deux types de champignons et le pak-choï dans la poêle chaude avec l'autre cuillère à soupe d'huile. Faites-les sauter jusqu'à ce qu'ils ramollissent.","Remettez le tofu cuit dans la poêle. Ajoutez la sauce aux huîtres, la sauce soja et le sucre. Remuez délicatement.","Mélangez la fécule de maïs avec une cuillère à café d'eau froide. Versez lentement le liquide en remuant délicatement en même temps. Faites cuire jusqu'à ce que la sauce épaississe, puis servez avec le riz."],
[["Note du chef","Un classique plat sans viande à la hongkongaise. Riche, copieux et réconfortant. Convient à toute la famille."],["Glucides","Le riz est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium, malgré l'utilisation de champignons, un légume riche en potassium. C'est parce que les quantités ont été réduites au minimum; veillez donc à respecter les quantités de tous les ingrédients et les tailles de portion.\nCette recette est aussi faible en phosphate, mais elle en contient tout de même, fourni par le tofu et le riz; par conséquent, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines, ce qui la rend adaptée aux personnes à qui l'on a conseillé de manger plus de protéines."],["Sans gluten","Utilisez une sauce soja sans gluten, comme le tamari, et une sauce aux huîtres sans gluten."],["Végétarien / Végane","Remplacez la sauce aux huîtres par une version végétarienne."],["Option plus saine","Pour augmenter les fibres de ce plat, envisagez d'utiliser du riz brun à grains entiers au lieu du riz blanc. Gardez à l'esprit que la sauce soja à faible teneur en sel et la sauce aux huîtres sont toutes deux des ingrédients riches en sel; mesurez-les donc soigneusement pour éviter d'ajouter du sel en trop."],["Conservation","Ce plat se déguste de préférence frais."],["Astuces","Pour réduire le temps de cuisson, coupez le tofu en cubes de 1 cm et faites-le cuire avec une cuillère à soupe d'huile supplémentaire."]],
[]),
(3372312,"Macaroni gratiné sans fromage",
"Préparé avec de la courge musquée pour une sauce crémeuse, ce délicieux plat végane est faible en sel, en potassium, en phosphate et en protéines; il convient donc à tout le monde.",
"4",None,
["1 courge musquée (environ 600 g)","175 ml de lait de coco entier","2 cuillères à café de moutarde de Dijon","1 cube de bouillon de légumes à faible teneur en sel","1 cuillère à café de vinaigre de cidre","250 g de macaronis","Poivre noir","100 g de chapelure","50 g de fromage végane râpé","30 g d'amandes effilées","1 cuillère à soupe de persil frais (facultatif)","200 g de brocoli"],
["Préchauffez le four à 160 °C / 140 °C chaleur tournante / thermostat gaz 3. Coupez la courge musquée en deux et retirez les graines. Placez-la côté chair vers le bas dans un plat à rôtir et versez 200 ml d'eau. Faites cuire au four pendant 1 heure 30 minutes.","Laissez la courge refroidir légèrement avant d'en retirer la chair à la cuillère. Mettez-la dans un mélangeur avec le lait de coco pour obtenir une purée lisse.","Une fois en purée, faites chauffer doucement dans une casserole. Ajoutez la moutarde de Dijon, le vinaigre de cidre et émiettez le cube de bouillon. Assaisonnez de poivre et ajoutez un peu d'eau à la sauce au besoin. Laissez mijoter 20 minutes jusqu'à ce qu'elle épaississe","Portez à ébullition une grande casserole d'eau. Ajoutez les macaronis et faites-les cuire 7 minutes. Ils continueront à cuire au four. Égouttez les pâtes et mélangez-les à la sauce en les versant dans un plat allant au four.","Mélangez la chapelure, les amandes, le fromage végane et le persil, le cas échéant. Saupoudrez sur les pâtes et faites cuire au four 10 minutes jusqu'à ce que le dessus soit doré.","Portez à ébullition une casserole d'eau et ajoutez le brocoli. Faites cuire jusqu'à ce qu'il soit tendre, égouttez et servez avec les pâtes."],
[["Note du chef","Variante d'un classique, cette version végane du macaroni au fromage est un délicieux repas réconfortant qui peut être congelé pour la cuisine en lots."],["Glucides","Les pâtes et la chapelure sont la principale source de glucides de ce plat, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Dans la plupart des plats véganes à base de fromage, on ajoute de la levure nutritionnelle pour donner le goût de fromage, mais la levure nutritionnelle est riche en potassium. Dans ce plat, on utilise plutôt de la courge musquée, ce qui ajoute une touche saine et maintient la teneur globale de la recette faible en potassium.\nCe plat est faible en phosphate, même s'il en contient un peu; par conséquent, si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est faible en protéines et convient si vous suivez un régime pauvre en protéines."],["Sans gluten","Utilisez des pâtes, de la chapelure et un bouillon sans gluten."],["Option plus saine","Pour augmenter les fibres de ce plat, essayez d'utiliser des pâtes de blé entier à la place des macaronis."],["Option plus économique","Ce plat est relativement peu coûteux. Cependant, vous pourriez essayer de le servir avec du brocoli si le brocoli-rave violet est hors saison ou cher. Pour économiser, vous pouvez faire votre propre chapelure."],["Conservation","Une fois refroidi, conservez-le dans un contenant hermétique au réfrigérateur. Consommez dans les 3 jours et réchauffez bien avant de servir. Si vous congelez, répartissez en portions à la fin de l'étape 4 dans un contenant hermétique. Décongelez complètement, puis ajoutez le mélange de garniture et poursuivez la cuisson à partir de l'étape 5."],["Astuces","Pour faire de la chapelure fraîche, déchirez le pain en morceaux et mettez-le dans un robot culinaire muni de la lame. Mixez le pain par à-coups jusqu'à obtenir une chapelure de la taille désirée.\nPour gagner du temps, vous pouvez acheter de la courge musquée fraîche déjà coupée, préemballée, ou surgelée, et la cuire selon les instructions de l'emballage avant de poursuivre à l'étape 2."]],
[]),
(3414864,"Gratin de chou-fleur à la caribéenne",
"Un repas faible en potassium et faible en sel, idéal à congeler comme repas prêt à manger après la dialyse. Il suffit d'ajouter un petit pain croustillant pour compléter le repas.",
"2",None,
["400 g de chou-fleur, coupé en bouquets","150 ml de lait partiellement écrémé","20 g de beurre non salé","1 cuillère à soupe bien pleine de farine","Une pincée de poivre noir","1 petit oignon, finement haché","60 g de cheddar râpé",["Pour servir","2 petits pains croustillants"]],
["Préchauffez le four à 170 °C / 140 °C chaleur tournante / thermostat gaz 3. Mettez les bouquets de chou-fleur dans une casserole d'eau et faites bouillir. Laissez bouillir 3 minutes, puis retirez du feu et égouttez.","Dans une autre casserole, faites fondre le beurre. Retirez du feu et incorporez la farine jusqu'à consistance lisse. Remettez sur le feu et ajoutez le lait, en fouettant pour mélanger et épaissir. Vous obtiendrez un roux (sauce blanche).","Ajoutez le poivre noir, l'oignon et le fromage râpé à la sauce blanche. Remuez pour mélanger.","Placez le chou-fleur égoutté dans un plat allant au four et versez lentement votre sauce dessus.","Placez le chou-fleur égoutté dans un plat allant au four et versez lentement votre sauce dessus.","Divisez en deux portions et servez avec un petit pain croustillant pour un repas principal complet."],
[["Note du chef","Un accompagnement traditionnel, mais servi comme plat principal avec du pain croustillant pour le compléter."],["Glucides","Le petit pain, la farine et le lait sont la principale source de glucides de ce plat, et les valeurs sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Bien que ce repas contienne un peu de potassium, dans l'ensemble, en respectant la taille de portion suggérée, ce repas est faible en potassium et peut être savouré dans le cadre d'un régime pauvre en potassium. Notez qu'il ne s'agit pas d'un accompagnement, mais d'un repas complet.\nCe plat est riche en phosphate, principalement à cause du fromage et du lait; par conséquent, si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce repas.\nNote : si vous suivez un régime pauvre en phosphate, assurez-vous d'inclure le lait de cette recette dans votre allocation de la journée."],["Protéines","Cette recette est riche en protéines, fournies par le fromage et le lait. Si on vous a conseillé de réduire vos protéines, envisagez de remplacer le lait de vache par du lait de riz, d'avoine ou d'amande."],["Sans gluten","Utilisez de la farine sans gluten et des petits pains sans gluten."],["Conservation","Une fois cuit, ce plat peut être conservé au réfrigérateur jusqu'à 3 jours et réchauffé. Il peut aussi être congelé avant ou après la cuisson au four."]],
[]),
(3434975,"Pâtés à la viande de bœuf à la caribéenne",
"Un plat savoureux et nourrissant, accompagné d'une délicieuse salade fraîche. Dans l'ensemble, cette recette est faible en sel, en potassium et en phosphate.",
"4",None,
[["Pâtés au bœuf","1 cuillère à café d'huile végétale"],["Pâtés au bœuf","1 petit oignon (ou ½ oignon moyen), finement haché"],["Pâtés au bœuf","2 gousses d'ail, écrasées"],["Pâtés au bœuf","250 g de bœuf haché (5 % de matières grasses)"],["Pâtés au bœuf","1 cuillère à café de curcuma"],["Pâtés au bœuf","2 cuillères à soupe de concentré de tomate"],["Pâtés au bœuf","1 cuillère à café d'assaisonnement vert ou 1 cube de bouillon à très faible teneur en sel"],["Pâtés au bœuf","10 g de coriandre fraîche, grossièrement hachée (1 poignée)"],["Pâtés au bœuf","500 g de pâte brisée ou feuilletée en bloc"],["Pâtés au bœuf","1 œuf, battu"],["Salade","1 petite boîte d'ananas (égoutté et haché)"],["Salade","3 tomates moyennes, tranchées"],["Salade","½ concombre, coupé en cubes"],["Salade","½ poivron rouge et ½ poivron jaune, coupés en cubes"],["Salade","1 petite boîte de 200 g de maïs ou 160 g de maïs surgelé"],["Salade","2 cuillères à soupe de vinaigre de vin blanc"],["Salade","½ cuillère à café de sucre"],["Salade","Une pincée de poivre noir"]],
["Faites chauffer à feu moyen une grande poêle avec couvercle; ajoutez l'huile et faites revenir l'oignon 5 minutes, puis ajoutez l'ail écrasé et le bœuf haché et faites cuire jusqu'à ce que la viande hachée soit dorée. Ajoutez une cuillère à café de curcuma, le concentré de tomate, l'assaisonnement vert ou le cube de bouillon et 200 ml d'eau, mélangez bien. Couvrez et laissez mijoter 15 minutes.","Après 15 minutes de mijotage à couvert, retirez le couvercle, incorporez la coriandre fraîche hachée et laissez mijoter encore 5 minutes sans couvercle. Laissez le mélange refroidir pendant que vous préparez la pâte.","Préchauffez le four à 200 °C / 180 °C chaleur tournante / thermostat gaz 7. Sur une surface farinée, abaissez le bloc de pâte brisée à une épaisseur de 2 mm. À l'aide d'une soucoupe ou d'une petite assiette ou d'un petit bol pour tracer le contour, marquez 8 cercles de 15 cm de diamètre.","Prélevez le mélange de viande hachée de la poêle et déposez-le sur un côté de chacun des cercles de pâte. Battez l'œuf. Badigeonnez le bord des cercles de pâte de dorure à l'œuf, repliez et scellez (appuyez avec une fourchette pour bien sceller). Placez les pâtés sur une plaque de cuisson chemisée et badigeonnez le dessus de dorure à l'œuf. Faites cuire 20 à 30 minutes ou jusqu'à ce qu'ils soient dorés.","Pendant la cuisson des pâtés, préparez la salade. Dans un grand bol, mettez l'ananas, le maïs, les tomates, le concombre et les poivrons. Mélangez le vinaigre, le sucre et le poivre noir dans un petit pichet et versez sur la salade.","Sortez les pâtés du four lorsqu'ils sont bien chauds et que la pâte est dorée et croustillante partout. Laissez refroidir 5 minutes, puis servez deux pâtés par personne, avec la salade."],
[["Note du chef","Ces pâtés au bœuf traditionnellement caribéens constituent un excellent plat principal lorsqu'ils sont servis avec cette salade colorée."],["Glucides","La pâte est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré l'utilisation de certains ingrédients riches en potassium, comme les tomates et le concentré de tomate, cette recette est faible en potassium si l'on respecte les quantités des ingrédients et les tailles de portion. Elle convient donc aux personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation.\nCette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par le bœuf; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est une source de protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse. Si on vous a conseillé de manger moins de protéines, vous pouvez remplacer la moitié du bœuf par des haricots rouges ou une autre légumineuse (voir les options végétarienne et végane)."],["Sans gluten","Utilisez de la pâte sans gluten."],["Végétarien","Remplacez le bœuf par une boîte de 400 g de haricots rouges ou une autre légumineuse (égouttée)."],["Végane","Remplacez le bœuf par une boîte de 400 g de haricots rouges ou une autre légumineuse (égouttée)."],["Conservation","Une fois les pâtés cuits, laissez-les refroidir et conservez-les dans un contenant hermétique jusqu'à 3 jours. Peuvent être réchauffés ou mangés froids."]],
[]),
(3448923,"Quiche à la betterave et au fromage de chèvre",
"Une quiche gourmande, faible en sel mais pleine de saveur.",
"6",None,
[["1 portion de pâte salée","300 g de farine ordinaire"],["1 portion de pâte salée","5 g de graines d'oignon noir"],["1 portion de pâte salée","10 g de parmesan, finement râpé"],["1 portion de pâte salée","1 pincée de paprika"],["1 portion de pâte salée","125 g de beurre non salé froid, en cubes"],["1 portion de pâte salée","1 gros œuf"],["Pour la garniture","150 g de betterave cuite (bouillie), en cubes"],["Pour la garniture","150 g de fromage de chèvre frais, émietté"],["Pour la garniture","225 ml de crème épaisse"],["Pour la garniture","3 œufs"],["Pour la garniture","50 g de cheddar, râpé"],["Pour la garniture","Une pincée de poivre noir moulu"],["Salade d'accompagnement à servir","80 g de roquette"],["Salade d'accompagnement à servir","4 tomates moyennes, hachées"],["Salade d'accompagnement à servir","½ concombre, haché"],["Salade d'accompagnement à servir","Jus de 1 citron ou de 1 lime"]],
["Pour préparer la pâte : mettez la farine, les graines d'oignon, le parmesan et le paprika dans un bol et mélangez. Ajoutez le beurre et incorporez-le du bout des doigts jusqu'à obtenir une texture de chapelure fine.","Ajoutez l'œuf, en mélangeant avec un couteau jusqu'à ce que le tout commence à se lier. Utilisez ensuite vos mains pour former une boule de pâte. Renversez sur une surface farinée et pétrissez un peu pour lisser la pâte. Enveloppez dans de la pellicule plastique et mettez de côté jusqu'au moment de l'utiliser.","Pour préparer la quiche : beurrez et farinez un cercle à tarte de 23 cm (9 pouces) de diamètre. Sur une surface farinée, abaissez la pâte jusqu'à ce qu'elle soit assez grande pour garnir le cercle à tarte. Déposez délicatement la pâte dans le moule et pressez-la dans les coins. Piquez le fond de la pâte avec une fourchette.","Préchauffez le four à 180 °C / 160 °C chaleur tournante / thermostat gaz 4. Mettez la betterave en cubes et le fromage de chèvre émietté dans le fond de tarte. Fouettez les œufs et la crème épaisse ensemble dans un pichet, ajoutez le poivre. Versez le mélange sur la betterave et le fromage de chèvre.","Saupoudrez le cheddar râpé sur le dessus de la quiche, puis faites cuire au four 25 minutes jusqu'à ce qu'elle soit bien dorée et que le mélange d'œufs soit pris. Laissez refroidir dans le moule. Une fois refroidie, démoulez et servez.","Préparez la salade en mélangeant la roquette, les tomates et le concombre, puis assaisonnez avec le jus de citron ou de lime. Servez en six portions."],
[["Note du chef","Un plat de souper agréable ou parfait pour une occasion spéciale. Les parts restantes font d'excellents lunchs à emporter."],["Glucides","La pâte est la principale source de glucides de ce plat, et les valeurs sont fournies pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Bien que cette recette contienne de la betterave, des tomates et d'autres légumes de salade riches en potassium, dans l'ensemble, en respectant les tailles de portion suggérées, ce plat est faible en potassium et peut être savouré dans le cadre d'un régime pauvre en potassium.\nMême si ce plat est faible en phosphate, il en contient un peu, fourni par le fromage. Par conséquent, si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est faible en protéines; il convient donc aux personnes à qui l'on a conseillé de réduire leur apport en protéines."],["Sans gluten","La pâte peut être préparée avec de la farine sans gluten et une petite cuillère à café de gomme xanthane."],["Conservation","Cette recette se conserve trois jours au réfrigérateur. Elle peut être servie froide dans les lunchs à emporter."],["Astuces","Cette recette peut aussi être préparée en quiches individuelles à l'aide d'un moule à muffins. Assurez-vous simplement que le moule est bien beurré et fariné au préalable et faites cuire pendant un temps réduit de 15 minutes."]],
[]),
(3465396,"Cari de courge musquée et de pois chiches",
"Un cari végétarien riche en fibres et nourrissant, faible en protéines, en potassium, en phosphate et en sel. Parfait pour les personnes qui réduisent leurs protéines.",
"4",None,
["1 cuillère à soupe d'huile d'olive","1 courge musquée (environ 400 g)","1 oignon rouge","2 cuillères à café de pâte de cari douce","300 ml de bouillon de légumes à teneur réduite en sel","400 g de tomates concassées","400 g de pois chiches en conserve","3 cuillères à soupe de yogourt grec sans gras","160 g de riz non cuit","30 g de coriandre fraîche","4 chapatis de blé entier"],
["Pelez la courge musquée, retirez les graines et coupez-la en dés. Faites chauffer l'huile dans une grande poêle et faites cuire la courge musquée 2 à 3 minutes jusqu'à ce qu'elle soit légèrement dorée. Coupez l'oignon en dés et ajoutez-le dans la poêle, avec la pâte de cari, et faites revenir encore 3 à 4 minutes.","Versez le bouillon, puis couvrez et laissez mijoter 15 à 20 minutes, ou jusqu'à ce que la courge soit tendre. Égouttez et rincez les pois chiches, puis ajoutez-les avec les tomates au cari. Faites cuire doucement 3 à 4 minutes, jusqu'à ce que les tomates ramollissent légèrement.","Portez une casserole d'eau à ébullition. Rincez le riz et ajoutez-le à l'eau bouillante. Couvrez et réduisez le feu pour laisser mijoter 20 minutes ou jusqu'à ce qu'il soit cuit.","Retirez le cari du feu et incorporez le yogourt et la coriandre hachée. Servez avec le riz cuit et un chapati de blé entier si vous le désirez."],
[["Note du chef","Ce cari de légumes rapide et facile est un choix savoureux pour un soir de semaine. Utilisez un yogourt végétal ou de la crème de coco pour un repas végane."],["Glucides","La principale source de glucides de ce plat provient du riz et des chapatis. La valeur en glucides de ce plat est fournie pour les personnes formées à l'ajustement de l'insuline. Si vous servez sans chapatis, vous pouvez augmenter la quantité de riz de 40 g à 60 g de riz non cuit par portion."],["Potassium/phosphate","Bien que ce plat contienne certains ingrédients riches en potassium, comme les tomates en conserve et la courge musquée, les quantités utilisées dans la recette ont été réduites au minimum pour que l'ensemble du repas reste faible en potassium et puisse donc être savouré si vous suivez une restriction en potassium.\nDans l'ensemble, ce plat est faible en phosphate, mais si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est relativement faible en protéines par portion et convient donc si on vous a conseillé de suivre un régime pauvre en protéines. Si on vous a conseillé de suivre un régime riche en protéines, vous pouvez le servir avec 170 g de poulet si vous mangez de la viande. Il peut être coupé en dés et ajouté à l'étape 2."],["Sans gluten","Servie avec du riz, cette recette est sans gluten."],["Végane","Utilisez un yogourt végétal ou de la crème de coco."],["Option plus saine","La saveur de ce plat provient de toute la pâte de cari et des herbes; l'ajout de sel n'est donc pas nécessaire. Le bouillon contiendra un peu de sel, mais des cubes ou des pots de bouillon à faible ou très faible teneur en sel sont facilement disponibles dans les supermarchés."],["Option plus économique","Ce plat est relativement économique. Pour vous faciliter la vie, essayez d'utiliser de la courge musquée préparée ou surgelée, déjà pelée et coupée en dés !"],["Conservation","Si vous ne mangez pas tout le cari immédiatement, séparez-en une partie avant d'ajouter le yogourt. Laissez refroidir, placez dans un contenant hermétique, réfrigérez et consommez dans les deux jours. Réchauffez et incorporez le yogourt avant de servir. Si vous congelez le cari, mettez-le en portions dans un contenant fermé. Décongelez et réchauffez bien, en incorporant le yogourt avant de servir. Le riz doit être servi chaud et mangé immédiatement après sa première cuisson; ne le gardez pas pour le réchauffer. Servez avec du riz fraîchement cuit."]],
[]),
]
build(R,"out_xfr11_part5.json")
